SourceCode.Declaration:
/// <summary>
/// Extension of table PurchAgreementHeader
/// </summary>
[ExtensionOf(tableStr(PurchAgreementHeader))]
final class AVAPurchAgreementHeaderDbt_Extension
{
}

Method.Source:
public void insert()
{
    next insert();

    this.avaCreateMarkupTrans(false);
}

public void update()
{
    PurchAgreementHeader avaAgreementHeaderOrig = this.orig();
    AgreementHeaderDefault avaHeaderDefaultOrig = this.agreementHeaderDefault().orig();
    next update();

    if (this.VendAccount != avaAgreementHeaderOrig.VendAccount ||
        this.agreementHeaderDefault().MiscChargeGroup  != avaHeaderDefaultOrig.MiscChargeGroup)
    {
        this.avaCreateMarkupTrans();
    }

}

/// <summary>
/// updates AVAOrderConfirmation field in related AgreementLine records
/// </summary>
public void avaUpdateAgreementLineOrderConfirmation()
{
    AgreementLine agreementLine;

    ttsbegin;

    while select forupdate agreementLine
        where agreementLine.Agreement == this.RecId
        && agreementLine.IsDeleted == NoYes::No
    {
        agreementLine.AVAOrderConfirmation = this.AVAOrderConfirmation;

        agreementLine.doUpdate();
    }

    ttscommit;

}

/// <summary>
/// Updates the effective price of all related agreement lines
/// </summary>
public void avaUpdateALineEffectivePrice()
{
    AgreementLine avaAgreementLine;

    ttsbegin;

    update_recordset avaAgreementLine
        setting AVAEffectivePrice = this.AVAEffectivePrice
        where avaAgreementLine.Agreement == this.RecId
           && avaAgreementLine.IsDeleted == NoYes::No;

    ttscommit;
}

/// <summary>
/// Updates MarkupTrans for lines
/// </summary>
void avaModifiedMarkupGroup()
{
    AgreementLine  avaAgreementLine;

    while select avaAgreementLine
        index hint AgreementHeaderIdx
        where avaAgreementLine.Agreement    == this.RecId
           && !avaAgreementLine.IsDeleted
    {
        avaAgreementLine.avaCreateMarkupTrans(this, true);
    }
}

/// <summary>
/// Create <c>MarkupTrans</c> records
/// </summary>
/// <param name = "_deleteExistingMarkupTrans">boolean</param>
void  avaCreateMarkupTrans(
    boolean _deleteExistingMarkupTrans = true
)
{
    AgreementHeaderDefault avaHeaderDefault = this.agreementHeaderDefault();

    if (avaHeaderDefault.AVASkipCreateMarkup == NoYes::No)
    {

        Markup::insertMarkupTrans(HeadingLine::Heading,
                                MarkupModuleType::Vend,
                                this,
                                this.VendAccount,
                                avaHeaderDefault.MiscChargeGroup,
                                this.Currency,
                                this.Language,
                                '',
                                avaHeaderDefault.MiscChargeGroup,
                                false,
                                _deleteExistingMarkupTrans,
                                avaHeaderDefault.DeliveryMode,
                                DlvMode::find(avaHeaderDefault.DeliveryMode).MarkupGroup);
    }
}
